"use client";
// @zeus-internal
import { ArrowDownToLine, Landmark, Wallet } from "lucide-react";
import type { ReactNode } from "react";
import { BALANCE_POINTS, FEATURED, formatCurrency, formatWhole, METRICS } from "./01-trends/data";
import { NumberTicker } from "./01-trends/number-ticker";
import { TrendChart } from "./01-trends/trend-chart";
const formatFraction = (cents: number) => `.${String(cents).padStart(2, "0")}`;
function MetricValue({ value }: {
    value: number;
}) {
    const whole = Math.trunc(value);
    const cents = Math.round((value - whole) * 100);
    return (<span className="art:inline-flex art:whitespace-nowrap art:text-3xl art:font-medium art:tabular-nums art:tracking-tight art:@7xl/metrics:text-4xl">
      <span className="art:sr-only">{formatCurrency(value)}</span>
      <span aria-hidden="true" className="art:inline-flex art:items-center">
        <NumberTicker value={whole} format={formatWhole}/>
        <NumberTicker value={cents} format={formatFraction} className="art:text-muted-foreground"/>
      </span>
    </span>);
}
function MetricBody({ icon, label, value, note }: {
    icon: ReactNode;
    label: string;
    value: number;
    note: string;
}) {
    return (<div className="art:flex art:min-w-0 art:flex-col art:items-start">
      <span aria-hidden="true" className="art:mb-6 art:grid art:size-11 art:place-items-center art:rounded-full art:border art:border-border art:text-foreground art:[&>svg]:size-5">
        {icon}
      </span>
      <dt className="art:text-xl art:font-medium art:text-foreground">{label}</dt>
      <dd className="art:mt-3">
        <MetricValue value={value}/>
      </dd>
      <p className="art:mt-5 art:text-sm art:text-muted-foreground">{note}</p>
    </div>);
}
const METRIC_ICONS: Record<(typeof METRICS)[number]["id"], ReactNode> = {
    reserved: <Landmark />,
    payouts: <ArrowDownToLine />,
};
export default function KpiOverviewTrends() {
    return (<div className="art:w-full art:max-w-screen-2xl">
      <section aria-label="Key performance indicators" className="art:@container/metrics art:w-full art:min-w-0">
        <dl className="art:grid art:grid-cols-1 art:gap-4 art:@2xl:grid-cols-2 art:@5xl:grid-cols-4">
          <div className="art:@container/featured art:min-w-0 art:rounded-3xl art:border art:border-border art:bg-background art:p-6 art:@2xl:col-span-2">
            <div className="art:grid art:items-center art:gap-6 art:@md/featured:grid-cols-2">
              <MetricBody icon={<Wallet />} label={FEATURED.label} value={FEATURED.value} note={FEATURED.note}/>
              <TrendChart label={FEATURED.label} points={BALANCE_POINTS}/>
            </div>
          </div>
          {METRICS.map((metric) => (<div key={metric.id} className="art:flex art:min-w-0 art:items-center art:rounded-3xl art:border art:border-border art:bg-background art:p-6">
              <MetricBody icon={METRIC_ICONS[metric.id]} label={metric.label} value={metric.value} note={metric.note}/>
            </div>))}
        </dl>
      </section>
    </div>);
}

// @zeus-internal
export interface TrendPoint {
    value: number;
    label: string;
}
const BALANCES = [
    43180, 45140, 43220, 43480, 46240, 45910, 44620, 46410, 48260, 46940, 47210, 50180, 49810, 48760, 50620, 52110, 51320,
    51980, 54060, 54410, 53740, 55190, 56540, 56080, 56620, 57910, 58120, 58210, 58305, 58432.76,
];
export const BALANCE_POINTS: readonly TrendPoint[] = BALANCES.map((value, index) => ({
    value,
    label: `Sep ${index + 1}`,
}));
export const FEATURED = {
    id: "balance",
    label: "Cash balance",
    value: 58432.76,
    note: "+$15,252.76 \u00B7 35.32% this month",
} as const;
export const METRICS = [
    { id: "reserved", label: "Reserved funds", value: 18250.4, note: "Assigned to 4 budgets" },
    { id: "payouts", label: "Pending payouts", value: 842.35, note: "Arriving in 2 business days" },
] as const;
const CURRENCY = new Intl.NumberFormat("en-US", {
    style: "currency",
    currency: "USD",
    minimumFractionDigits: 2,
    maximumFractionDigits: 2,
});
const CURRENCY_WHOLE = new Intl.NumberFormat("en-US", {
    style: "currency",
    currency: "USD",
    minimumFractionDigits: 0,
    maximumFractionDigits: 0,
});
export function formatCurrency(value: number): string {
    return CURRENCY.format(value);
}
export function formatWhole(value: number): string {
    return CURRENCY_WHOLE.format(value);
}

"use client";
// @zeus-internal
import { ArtemisRollingNumber } from "../../../../lib/rolling-number";
export interface NumberTickerProps { value: number; format: (value: number) => string; className?: string; duration?: number; stagger?: number; prefix?: string; suffix?: string; label?: string; entrance?: boolean; }
export function NumberTicker({ value, format, className, duration = 0.6, stagger = 0.02, prefix, suffix, label }: NumberTickerProps) { return <ArtemisRollingNumber text={format(Math.round(value))} className={className} duration={duration} stagger={stagger} prefix={prefix} suffix={suffix} label={label} activation={"in-view"} amount={0.6}/>; }

"use client";
// @zeus-internal
import { useId } from "react";
import { Area, AreaChart, CartesianGrid, ResponsiveContainer, Tooltip, type TooltipContentProps, XAxis, YAxis } from "recharts";
import type { NameType, ValueType } from "recharts/types/component/DefaultTooltipContent";
import { formatCurrency, type TrendPoint } from "./data";
const CHART_EASING = "cubic-bezier(0.16, 1, 0.3, 1)";
function TrendTooltip({ active, payload, label }: TooltipContentProps<ValueType, NameType>) {
    if (!active || !payload?.length)
        return null;
    const value = payload[0]?.value;
    return (<div className="art:rounded-xl art:border art:border-border art:bg-background art:px-3 art:py-2 art:text-xs">
      <p className="art:text-muted-foreground">{label}</p>
      <p className="art:mt-1 art:font-medium art:tabular-nums art:text-foreground">{typeof value === "number" ? formatCurrency(value) : null}</p>
    </div>);
}
export function TrendChart({ label, points }: {
    label: string;
    points: readonly TrendPoint[];
}) {
    const gradientId = useId();
    const first = points[0]?.label;
    const middle = points[Math.floor((points.length - 1) / 2)]?.label;
    const last = points[points.length - 1]?.label;
    const ticks = [first, middle, last].filter((t): t is string => t !== undefined);
    return (<figure aria-label={`${label} history`} className="art:h-48 art:min-w-0">

      <ResponsiveContainer width="100%" height="100%" minWidth={0} debounce={1}>
        <AreaChart data={points as TrendPoint[]} margin={{ top: 12, right: 8, bottom: 0, left: 8 }}>
          <defs>
            <linearGradient id={gradientId} x1="0" y1="0" x2="0" y2="1">
              <stop offset="0%" stopColor="var(--artemis-primary)" stopOpacity={0.14}/>
              <stop offset="100%" stopColor="var(--artemis-primary)" stopOpacity={0}/>
            </linearGradient>
          </defs>
          <CartesianGrid vertical={false} stroke="var(--artemis-border)" strokeDasharray="3 6"/>
          <XAxis dataKey="label" ticks={ticks} interval="preserveStartEnd" tickLine={false} axisLine={false} tickMargin={12} height={32} tick={{ className: "art:text-xs", fill: "var(--artemis-muted-foreground)" }}/>
          <YAxis hide domain={["dataMin", "dataMax"]} tickCount={3}/>
          <Tooltip cursor={{ stroke: "var(--artemis-border)", strokeDasharray: "3 4" }} content={TrendTooltip}/>
          <Area type="monotone" dataKey="value" stroke="var(--artemis-primary)" strokeWidth={2} fill={`url(#${gradientId})`} animationDuration={600} animationEasing={CHART_EASING} activeDot={{ r: 4, fill: "var(--artemis-primary)", strokeWidth: 2, stroke: "var(--artemis-background)" }}/>
        </AreaChart>
      </ResponsiveContainer>
      <table className="art:sr-only">
        <caption>{label} history</caption>
        <thead>
          <tr>
            <th scope="col">Date</th>
            <th scope="col">Value</th>
          </tr>
        </thead>
        <tbody>
          {points.map((point) => (<tr key={point.label}>
              <th scope="row">{point.label}</th>
              <td>{formatCurrency(point.value)}</td>
            </tr>))}
        </tbody>
      </table>
    </figure>);
}

"use client";
// @zeus-internal
import { animate, motion, useInView, useReducedMotion } from "motion/react";
import { useEffect, useRef, useState } from "react";
import { ARTEMIS_EASE_OUT } from "./ease";
export interface ArtemisRollingNumberProps {
  text: string;
  duration?: number;
  stagger?: number;
  className?: string;
  reducedMotion?: boolean;
  blur?: boolean;
  activation?: "in-view" | "immediate" | "mount";
  amount?: number;
  prefix?: string;
  suffix?: string;
  label?: string;
  blurUpdatesOnly?: boolean;
  staggerDigitsOnly?: boolean;
}
function Wheel({ value, delay, duration, reduced, blur, fromZero, blurUpdatesOnly }: { value: string; delay: number; duration: number; reduced: boolean; blur: boolean; fromZero: boolean; blurUpdatesOnly: boolean }) {
  const rail = useRef<HTMLSpanElement>(null);
  const firstPaint = useRef(true);
  useEffect(() => {
    const initial = firstPaint.current;
    firstPaint.current = false;
    if (!rail.current) return;
    if (!blur || reduced || value === "0" && !blurUpdatesOnly) { rail.current.style.filter = "none"; return; }
    if (blurUpdatesOnly && initial) return;
    const playback = animate(rail.current, { filter: ["blur(10px)", "blur(0px)"] }, { duration: 0.32, delay, ease: ARTEMIS_EASE_OUT });
    return () => playback.stop();
  }, [value, blur, reduced, blurUpdatesOnly]);
  return <span className="art:relative art:inline-block" style={{ clipPath: "inset(0)", lineHeight: "1.1em", height: "1.1em", width: "1ch", textAlign: "center" }}>
    <span className="art:invisible">{value}</span>
    <motion.span ref={rail} className="art:absolute art:inset-x-0 art:top-0 art:flex art:flex-col art:items-center art:will-change-[transform,filter]" initial={fromZero && !reduced ? { y: 0 } : false} animate={{ y: `${-Number(value) * 11 / 10}em` }} transition={reduced ? { duration: 0 } : { duration, delay, ease: ARTEMIS_EASE_OUT }}>
      {Array.from({ length: 10 }, (_, digit) => <span key={digit} className="art:flex art:items-center art:justify-center art:leading-none" style={{ height: "1.1em" }}>{digit}</span>)}
    </motion.span>
  </span>;
}
export function ArtemisRollingNumber({ text, duration = 0.6, stagger = 0.02, className = "", reducedMotion, blur = false, activation = "in-view", amount = 0.6, prefix = "", suffix = "", label, blurUpdatesOnly = false, staggerDigitsOnly = false }: ArtemisRollingNumberProps) {
  const anchor = useRef<HTMLSpanElement>(null);
  const observed = useInView(anchor, { once: true, amount });
  const visible = activation !== "in-view" || observed;
  const preference = useReducedMotion() === true;
  const reduced = reducedMotion ?? preference;
  const [settled, setSettled] = useState(false);
  const firstText = useRef(text), changedSinceMount = useRef(false);
  if (text !== firstText.current) changedSinceMount.current = true;
  useEffect(() => {
    if (!visible || settled) return;
    const timer = setTimeout(() => setSettled(true), (duration + text.length * stagger) * 1000);
    return () => clearTimeout(timer);
  }, [visible, settled, duration, stagger, text.length]);
  return <span ref={anchor} className={`art:inline-flex art:items-baseline art:tabular-nums ${className}`}>
    <span className="art:sr-only">{label ?? prefix + text + suffix}</span>
    <span aria-hidden="true" className="art:inline-flex art:items-baseline">{prefix && <span>{prefix}</span>}{Array.from(text, (char, index) => /[0-9]/.test(char)
      ? <Wheel key={text.length - index} value={visible || reduced ? char : "0"} delay={settled || reduced || activation === "mount" && changedSinceMount.current ? 0 : (staggerDigitsOnly ? text.slice(0, index).replace(/\D/g, "").length : index) * stagger} duration={duration} reduced={reduced} blur={blur} fromZero={activation === "mount"} blurUpdatesOnly={blurUpdatesOnly}/>
      : <span key={text.length - index}>{char}</span>)}{suffix && <span>{suffix}</span>}</span>
  </span>;
}
